package co.edu.umb.boleteria.domain;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="reserva") public class Reserva { @Id @Column(name="id_reserva") UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="id_localidad",nullable=false) Localidad localidad; @Column(name="usuario_id",nullable=false,length=100) String usuarioId; @Column(nullable=false) int cantidad; @Column(name="fecha_creacion",nullable=false) Instant fechaCreacion; @Column(name="fecha_expiracion",nullable=false) Instant fechaExpiracion; @Enumerated(EnumType.STRING) @Column(nullable=false) EstadoReserva estado; protected Reserva(){} public Reserva(Localidad l,String u,int n,Instant now,Instant exp){id=UUID.randomUUID();localidad=l;usuarioId=u;cantidad=n;fechaCreacion=now;fechaExpiracion=exp;estado=EstadoReserva.ACTIVA;} public UUID getId(){return id;} public Localidad getLocalidad(){return localidad;} public int getCantidad(){return cantidad;} public Instant getFechaExpiracion(){return fechaExpiracion;} public EstadoReserva getEstado(){return estado;} public void setEstado(EstadoReserva e){estado=e;} }
